package io.github.plrlr.autopilot.skills.evolved;

import io.github.plrlr.autopilot.plan.Option;
import io.github.plrlr.autopilot.skills.Fail;
import net.minecraft.core.BlockPos;
import net.minecraft.world.phys.Vec3;

import java.util.HashSet;
import java.util.Set;

public class SwimOut extends EvolvedSkill {
	private static final Set<BlockPos> BAD = new HashSet<>();
	private BlockPos target;
	private float heading;
	private double bestDist;
	private Vec3 checkPos;
	private int lastCheck;
	private int dryTicks;
	private int retargets;

	public static Option offer(Context c) {
		if (c.main() == null || !"shore".equals(c.main().skill())) return null;
		if (!"shore".equals(c.lastSkill())) return null;
		if (!"TIMEOUT".equals(c.lastCode()) && !"STUCK".equals(c.lastCode())) return null;
		if (Player.gameSeconds() - c.lastEndSeconds() > 120) return null;
		return new Option("swim_out", null, "shore just failed (" + c.lastCode() + "): swim by hand to seen land instead of repeating it");
	}

	@Override
	public String name() { return "swim_out"; }

	@Override
	protected void start() {
		timeoutTicks = 20 * 60;
		if (BAD.size() > 64) BAD.clear();
		heading = Player.yaw();
		pickTarget();
		checkPos = Player.pos();
		lastCheck = 0;
	}

	private void pickTarget() {
		BlockPos me = Player.feet();
		Set<BlockPos> aside = new HashSet<>(BAD);
		target = null;
		for (int i = 0; i < 4; i++) {
			BlockPos l = memory.nearestLand(aside);
			if (l == null) break;
			// On land already (tiny island / no room): look for land further away.
			if (!Player.inWater() && hdist(l, me) < 6) { aside.add(l); continue; }
			target = l;
			break;
		}
		bestDist = target == null ? 0 : hdist(target, me);
	}

	private static double hdist(BlockPos a, BlockPos b) {
		double dx = a.getX() - b.getX(), dz = a.getZ() - b.getZ();
		return Math.sqrt(dx * dx + dz * dz);
	}

	@Override
	protected void tick() {
		if (!Player.inWater() && Player.onGround()) {
			if (++dryTicks >= 10 && (target == null || hdist(target, Player.feet()) < 4 || ticks > 100)) {
				done("swam out onto dry ground at " + Player.feet());
				return;
			}
		} else dryTicks = 0;

		Vec3 p = Player.pos();
		if (target != null) {
			double dx = target.getX() + 0.5 - p.x, dz = target.getZ() + 0.5 - p.z;
			if (dx * dx + dz * dz > 0.25) heading = (float) (Math.atan2(dz, dx) * 180 / Math.PI) - 90f;
			double d = Math.sqrt(dx * dx + dz * dz);
			if (d < 1.2 && Player.inWater()) {
				// Remembered land turned out to be water here; try another.
				BAD.add(target);
				pickTarget();
			}
		} else if (ticks % 40 == 0) {
			pickTarget();
		}

		Player.stopWalking();
		Player.turn(heading, Player.eyesInWater() ? -20f : 0f);
		Player.press(Player.Key.SPRINT, false);
		Player.press(Player.Key.FORWARD, true);
		Player.press(Player.Key.JUMP, Player.inWater() || !Player.onGround() || ticks % 10 < 3);

		if (ticks - lastCheck >= 160) {
			double moved = Math.hypot(p.x - checkPos.x, p.z - checkPos.z);
			boolean closer = target != null && hdist(target, Player.feet()) < bestDist - 2;
			if (target != null) bestDist = Math.min(bestDist, hdist(target, Player.feet()));
			if (moved < 2 || (target != null && !closer)) {
				if (++retargets > 5) { fail(Fail.STUCK, "no swimming progress after " + retargets + " headings"); return; }
				if (target != null) BAD.add(target);
				pickTarget();
				if (target == null) heading += 90f;
			}
			checkPos = p;
			lastCheck = ticks;
		}
	}
}
